package com.labmaker.app;
import org.junit.Test;import static org.junit.Assert.*;import okhttp3.*;import okhttp3.mockwebserver.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;
public class APIModelsTest {
 byte[] json(String value){return value.getBytes(StandardCharsets.UTF_8);}
 OkHttpClient client(){return new OkHttpClient.Builder().followRedirects(false).followSslRedirects(false).retryOnConnectionFailure(false).callTimeout(2,TimeUnit.SECONDS).build();}
 @Test public void modelIdsAreBoundedDeduplicatedSortedAndSecretsNotReturned()throws Exception {JSONObject result=APIModels.parse(json("{\"data\":[{\"id\":\"z\"},{\"id\":\" a \"},{\"id\":\"z\"},{\"id\":null},{\"id\":\"prefix-PRIVATEKEY\"},{\"id\":\"bad\\nname\"}],\"has_more\":true}"),"PRIVATEKEY");assertEquals("[\"a\",\"z\"]",result.getJSONArray("models").toString());assertTrue(result.getBoolean("partial"));assertFalse(result.toString().contains("PRIVATEKEY"));}
 @Test public void emptyMalformedAndOversizeListsFailInsteadOfClaimingSuccess()throws Exception {for(String raw:new String[]{"{}","{\"data\":[]}","{\"data\":[{\"id\":\"\"}]}","not json"})try{APIModels.parse(json(raw),"");fail();}catch(Exception expected){}JSONArray rows=new JSONArray();for(int i=0;i<10001;i++)rows.put(new JSONObject().put("id","m"+i));try{APIModels.parse(new JSONObject().put("data",rows).toString().getBytes(StandardCharsets.UTF_8),"");fail();}catch(IOException expected){}}
 @Test public void draftKeysNeverBorrowCredentialsFromAnotherEndpoint()throws Exception {JSONObject stored=new JSONObject().put("endpoint","https://old.example/v1").put("key","old-key");assertEquals("old-key",APIModels.keyFor("https://old.example/v1","",stored));assertEquals("new-key",APIModels.keyFor("https://new.example/v1","new-key",stored));try{APIModels.keyFor("https://new.example/v1","",stored);fail();}catch(IOException expected){}try{APIModels.keyFor("https://old.example/v1","bad\nkey",stored);fail();}catch(IOException expected){}}
 @Test public void discoveryUsesGetAuthorizationAndReturnsIdsOnly()throws Exception {try(MockWebServer server=new MockWebServer()){server.start();server.enqueue(new MockResponse().setBody("{\"data\":[{\"id\":\"vision/model\"}]}"));Call call=client().newCall(new Request.Builder().url(server.url("/v1/models")).header("Authorization","Bearer example-key").get().build());JSONObject result=APIModels.read(call,"example-key");assertEquals("vision/model",result.getJSONArray("models").getString(0));RecordedRequest request=server.takeRequest();assertEquals("GET",request.getMethod());assertEquals("/v1/models",request.getPath());assertEquals("Bearer example-key",request.getHeader("Authorization"));assertEquals(0,request.getBodySize());assertNull(request.getHeader("Cookie"));assertEquals(1,server.getRequestCount());}}
 @Test public void redirectsAuthenticationAndUnsupportedServicesDoNotRetry()throws Exception {for(int code:new int[]{302,401,403,404,405,429})try(MockWebServer server=new MockWebServer()){server.start();server.enqueue(new MockResponse().setResponseCode(code).setHeader("Location",server.url("/other")));try{APIModels.read(client().newCall(new Request.Builder().url(server.url("/models")).build()),"key");fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("HTTP "+code));}assertEquals(1,server.getRequestCount());}}
 @Test public void responseBoundAndCancellationAreEnforced()throws Exception {try(MockWebServer server=new MockWebServer()){server.start();server.enqueue(new MockResponse().setBody("x".repeat(1024*1024+1)));try{APIModels.read(client().newCall(new Request.Builder().url(server.url("/models")).build()),"key");fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("1 MB"));}Call cancelled=client().newCall(new Request.Builder().url(server.url("/models")).build());cancelled.cancel();try{APIModels.read(cancelled,"key");fail();}catch(IOException expected){}assertEquals(1,server.getRequestCount());}}
 @Test public void connectionTestDraftDoesNotMutateStoredConfiguration()throws Exception {JSONObject stored=new JSONObject().put("endpoint","https://old.example/v1").put("model","stored-model").put("key","stored-key");String before=stored.toString();JSONObject draft=APIModels.draft("https://new.example/v1"," draft-model ","new-key",stored);assertEquals("draft-model",draft.getString("model"));assertEquals("new-key",draft.getString("key"));assertEquals(before,stored.toString());for(String name:new String[]{"", "x".repeat(257), "bad\nmodel"})try{APIModels.draft("https://old.example/v1",name,"",stored);fail();}catch(IOException expected){}}
 @Test public void malformedSecretsFailBeforeHeaderConstructionWithoutEcho()throws Exception {for(String key:new String[]{"private-密钥-value","private value","private\tvalue"})try{APIModels.keyFor("https://api.example","",new JSONObject().put("endpoint","https://api.example").put("key",key));fail();}catch(IOException error){assertEquals("密钥格式无效",error.getMessage());assertFalse(error.getMessage().contains(key));}}
}
